    counts_absent boolean NOT NULL DEFAULT false,
    counts_excused boolean NOT NULL DEFAULT false,
    counts_late boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    code varchar(40) NOT NULL,
    sort_order integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_attendance_type PRIMARY KEY (id),
    CONSTRAINT uq_attendance_type_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE attendance.attendance_type IS 'Configurable attendance mark (Present, Absent, Late, Excused, Medical...).';
COMMENT ON COLUMN attendance.attendance_type.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
