    attendance_date date NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    leave_request_id uuid,
    CONSTRAINT pk_attendance_record PRIMARY KEY (id, attendance_date),
    CONSTRAINT ck_attendance_record_status CHECK (status IN ('present', 'absent', 'late', 'excused'))
) PARTITION BY RANGE (attendance_date);
CREATE TABLE attendance.attendance_record_default PARTITION OF attendance.attendance_record DEFAULT;
