-- === P1-13: transactional outbox / inbox ===

CREATE TABLE attendance.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    publish_error text,
    CONSTRAINT pk_attendance_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE attendance.outbox_event IS 'Transactional outbox of the attendance module: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN attendance.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN attendance.outbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN attendance.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN attendance.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN attendance.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN attendance.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN attendance.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN attendance.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
COMMENT ON COLUMN attendance.outbox_event.publish_error IS 'Why the relay could not turn the row into an event (set aside, not published); NULL otherwise.';
CREATE INDEX ix_attendance_outbox_event_pending ON attendance.outbox_event (id) WHERE published_at IS NULL AND publish_error IS NULL;
CREATE TABLE attendance.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_attendance_inbox_event PRIMARY KEY (tenant_id, event_id)
);
COMMENT ON TABLE attendance.inbox_event IS 'Inbox of the attendance module: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN attendance.inbox_event.event_id IS 'Global id of the consumed event; recorded per tenant.';
COMMENT ON COLUMN attendance.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN attendance.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN attendance.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN attendance.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN attendance.inbox_event.processing_error IS 'Last handling error, if any.';
CREATE INDEX ix_attendance_inbox_event_processed ON attendance.inbox_event (processed_at) WHERE processed_at IS NOT NULL;

