CREATE POLICY tenant_isolation ON attendance.outbox_event USING (tenant_id = current_setting('app.tenant_id', true)::uuid);

-- === Review fixes: day-row uniqueness ignores soft-deleted rows ===

CREATE UNIQUE INDEX uq_attendance_record_1 ON attendance.attendance_record (sheet_id, student_id, attendance_date) WHERE deleted_at IS NULL;

-- === Module-local infrastructure (distributed deployment: no cross-schema access) ===
CREATE TABLE attendance.idempotency_key (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    user_id uuid,
    operation_name varchar(120) NOT NULL,
    request_hash varchar(64),
    response_status smallint,
    response_body text,
    locked_at timestamptz,
    completed_at timestamptz,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_attendance_idempotency_key PRIMARY KEY (id),
    CONSTRAINT uq_attendance_idempotency_key_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE attendance.idempotency_key IS 'Module-local idempotency store of the attendance module: stored outcome of a write carrying an Idempotency-Key; replays return the stored response. Rows expire after 24h (cleanup job).';
COMMENT ON COLUMN attendance.idempotency_key.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN attendance.idempotency_key.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN attendance.idempotency_key.idempotency_key IS 'Key sent by the client.';
COMMENT ON COLUMN attendance.idempotency_key.user_id IS 'Caller.';
COMMENT ON COLUMN attendance.idempotency_key.operation_name IS 'Operation the key was used on.';
COMMENT ON COLUMN attendance.idempotency_key.request_hash IS 'Hash of the request body; a replay with a different body is rejected.';
COMMENT ON COLUMN attendance.idempotency_key.response_status IS 'Stored HTTP status.';
COMMENT ON COLUMN attendance.idempotency_key.response_body IS 'Stored response body.';
COMMENT ON COLUMN attendance.idempotency_key.locked_at IS 'Set while the first attempt is still executing.';
COMMENT ON COLUMN attendance.idempotency_key.completed_at IS 'When the stored response was written.';
COMMENT ON COLUMN attendance.idempotency_key.expires_at IS 'When the row may be purged.';
COMMENT ON COLUMN attendance.idempotency_key.created_at IS 'Row creation time.';
COMMENT ON COLUMN attendance.idempotency_key.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN attendance.idempotency_key.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN attendance.idempotency_key.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN attendance.idempotency_key.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN attendance.idempotency_key.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE attendance.idempotency_key ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance.idempotency_key FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON attendance.idempotency_key USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE attendance.operation (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    operation_name varchar(120) NOT NULL,
    resource_type varchar(80),
    resource_id uuid,
    status varchar(20) NOT NULL DEFAULT 'running',
    progress_percent smallint,
    error_code varchar(60),
    error_message varchar(500),
    result_entity_type varchar(80),
    result_entity_id uuid,
    started_by_user_id uuid,
    started_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_attendance_operation PRIMARY KEY (id),
    CONSTRAINT ck_attendance_operation_status CHECK (status IN ('running', 'succeeded', 'failed', 'cancelled'))
);
COMMENT ON TABLE attendance.operation IS 'Module-local long-running operation record of the attendance module, returned by its async API calls; polled by clients until it finishes.';
COMMENT ON COLUMN attendance.operation.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN attendance.operation.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN attendance.operation.operation_name IS 'Operation id as exposed by the API (module.Method).';
COMMENT ON COLUMN attendance.operation.resource_type IS 'Kind of resource being worked on.';
COMMENT ON COLUMN attendance.operation.resource_id IS 'Id of that resource.';
COMMENT ON COLUMN attendance.operation.status IS 'running / succeeded / failed / cancelled.';
COMMENT ON COLUMN attendance.operation.progress_percent IS 'Progress, when the job reports it.';
COMMENT ON COLUMN attendance.operation.error_code IS 'Machine error code when failed.';
COMMENT ON COLUMN attendance.operation.error_message IS 'Human error summary when failed.';
COMMENT ON COLUMN attendance.operation.result_entity_type IS 'Kind of the produced record.';
COMMENT ON COLUMN attendance.operation.result_entity_id IS 'Id of the produced record.';
COMMENT ON COLUMN attendance.operation.started_by_user_id IS 'User who started it.';
COMMENT ON COLUMN attendance.operation.started_at IS 'Start time.';
COMMENT ON COLUMN attendance.operation.finished_at IS 'End time.';
COMMENT ON COLUMN attendance.operation.created_at IS 'Row creation time.';
COMMENT ON COLUMN attendance.operation.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN attendance.operation.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN attendance.operation.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN attendance.operation.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN attendance.operation.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE attendance.operation ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance.operation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON attendance.operation USING (tenant_id = current_setting('app.tenant_id', true)::uuid);

-- === Student records of persons (privacy tasks), kept from sis.student events ===
CREATE TABLE attendance.member_record (
    tenant_id uuid NOT NULL,
    record_id uuid NOT NULL,
    record_type varchar(20) NOT NULL,
    person_id uuid NOT NULL,
    source_version integer NOT NULL,
    synced_at timestamptz NOT NULL,
    CONSTRAINT pk_attendance_member_record PRIMARY KEY (tenant_id, record_id),
    CONSTRAINT ck_member_record_record_type CHECK (record_type IN ('student')),
    CONSTRAINT ck_member_record_source_version CHECK (source_version >= 1)
);
COMMENT ON TABLE attendance.member_record IS 'The person of each student record, kept from sis.student created/updated events (attendance never reads another module''s schema), so privacy''s tasks and the attendance.after_leaving sweep find a data principal''s attendance (AttendancePrivacyTaskHandler). Staff attendance lives in hrms (time_attendance), so no staff records are kept here.';
COMMENT ON COLUMN attendance.member_record.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN attendance.member_record.record_id IS 'sis.student.id (logical, maintained from its events): attendance_record.student_id.';
COMMENT ON COLUMN attendance.member_record.record_type IS 'student (sis.student); the one kind attendance keeps since staff attendance moved to hrms.';
COMMENT ON COLUMN attendance.member_record.person_id IS 'Person of the record (people.person.id), the data principal privacy''s tasks name.';
COMMENT ON COLUMN attendance.member_record.source_version IS 'Row version of the sis.student row this entry reflects; an event with an older or equal version is ignored.';
COMMENT ON COLUMN attendance.member_record.synced_at IS 'When the row was last changed by an event.';
CREATE INDEX ix_attendance_member_record_person ON attendance.member_record (tenant_id, person_id);
COMMENT ON INDEX attendance.ix_attendance_member_record_person IS 'Privacy tasks: the student records of the data principal.';
ALTER TABLE attendance.member_record ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance.member_record FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON attendance.member_record USING (tenant_id = current_setting('app.tenant_id', true)::uuid);

-- === Privacy tasks (design PRIVACY-AND-CONSENT-CENTRE §9.1, §10) and the module's scheduled jobs (core JobSchedule) ===
CREATE TABLE attendance.privacy_task_receipt (
    task_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    kind varchar(10) NOT NULL,
    payload jsonb NOT NULL,
    status varchar(15) NOT NULL DEFAULT 'received',
    result jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    CONSTRAINT pk_attendance_privacy_task_receipt PRIMARY KEY (task_id),
    CONSTRAINT ck_attendance_privacy_task_receipt_kind CHECK (kind IN ('task', 'retention')),
    CONSTRAINT ck_attendance_privacy_task_receipt_status CHECK (status IN ('received', 'done', 'partial', 'failed',
        'not_applicable')),
    CONSTRAINT ck_attendance_privacy_task_receipt_completed CHECK ((status = 'received') = (completed_at IS NULL))
);
COMMENT ON TABLE attendance.privacy_task_receipt IS 'The privacy tasks and retention runs privacy sent this module (privacy.rights_request.task_assigned, privacy.retention.due), one row per task or run id: a task dispatched again runs once, is retried after a failure and is answered again from the stored answer (privacy-client PrivacyTaskHandler). Ids, codes and counts only.';
COMMENT ON COLUMN attendance.privacy_task_receipt.task_id IS 'The rights-request task id or the retention run id privacy sent; the id the module answers with.';
COMMENT ON COLUMN attendance.privacy_task_receipt.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN attendance.privacy_task_receipt.kind IS 'task (a rights-request task) or retention (a retention run).';
COMMENT ON COLUMN attendance.privacy_task_receipt.payload IS 'The event''s data as privacy sent it: ids, codes and dates only.';
COMMENT ON COLUMN attendance.privacy_task_receipt.status IS 'received (waiting for the module''s job), done, partial, failed or not_applicable.';
COMMENT ON COLUMN attendance.privacy_task_receipt.result IS 'The answer published (<module>.privacy_task.completed or <module>.privacy_retention.completed): counts and codes; null while received.';
COMMENT ON COLUMN attendance.privacy_task_receipt.created_at IS 'When the task or run first arrived.';
COMMENT ON COLUMN attendance.privacy_task_receipt.completed_at IS 'When the module answered; null while received.';
CREATE INDEX ix_attendance_privacy_task_receipt_received ON attendance.privacy_task_receipt (tenant_id, created_at) WHERE status = 'received';
COMMENT ON INDEX attendance.ix_attendance_privacy_task_receipt_received IS 'The tasks and runs waiting for the module''s job, the oldest first.';
ALTER TABLE attendance.privacy_task_receipt ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance.privacy_task_receipt FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON attendance.privacy_task_receipt USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE attendance.job_schedule (
    job_code varchar(60) NOT NULL,
    tenant_id uuid NOT NULL,
    next_run_at timestamptz NOT NULL,
    lease_owner uuid,
    lease_until timestamptz,
    last_run_at timestamptz,
    failures integer NOT NULL DEFAULT 0,
    last_error varchar(500),
    CONSTRAINT pk_job_schedule PRIMARY KEY (job_code, tenant_id),
    CONSTRAINT ck_job_schedule_lease CHECK ((lease_owner IS NULL) = (lease_until IS NULL)),
    CONSTRAINT ck_job_schedule_failures CHECK (failures >= 0)
);
COMMENT ON TABLE attendance.job_schedule IS 'When each tenant is next due for each scheduled job of the module (core JobSchedule, ROADMAP ARC-4). A tenant is enrolled the first time it has work for the job. Job codes, tenant ids and times only, no personal data, and no row-level security: the job runner claims due rows across tenants, then runs each in its tenant''s own context.';
COMMENT ON COLUMN attendance.job_schedule.job_code IS 'The job (<module>.<name>): attendance.privacy_tasks (runs the privacy tasks and retention runs of attendance.privacy_task_receipt).';
COMMENT ON COLUMN attendance.job_schedule.tenant_id IS 'The tenant the job runs for.';
COMMENT ON COLUMN attendance.job_schedule.next_run_at IS 'When the tenant is next due.';
COMMENT ON COLUMN attendance.job_schedule.lease_owner IS 'The runner (a random id per process) holding the tenant''s run; null while no run is held.';
COMMENT ON COLUMN attendance.job_schedule.lease_until IS 'Until when the lease holds; after it another runner may take the run over.';
COMMENT ON COLUMN attendance.job_schedule.last_run_at IS 'When the last run ended, finished or failed.';
COMMENT ON COLUMN attendance.job_schedule.failures IS 'Failed runs in a row; the retry delay doubles with each.';
COMMENT ON COLUMN attendance.job_schedule.last_error IS 'Why the last run failed (exception class and message, first 500 characters); null after a finished run.';
CREATE INDEX ix_job_schedule_due ON attendance.job_schedule (next_run_at);
COMMENT ON INDEX attendance.ix_job_schedule_due IS 'The due runs, the longest overdue first.';

